<?php require 'config.php';require_login();$id=$_SESSION['user_id'];$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$id]);$u=$q->fetch();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$dept=trim($_POST['department']??'');$year=($_POST['graduation_year']??'')?:null;$skills=trim($_POST['skills']??'');$resume=$u['resume'];if(isset($_FILES['resume'])&&$_FILES['resume']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['resume'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>2*1024*1024){$err='Upload a PDF under 2 MB.';}else{$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($ext!=='pdf'||$mime!=='application/pdf'){$err='Only PDF resumes are allowed.';}else{$dir=__DIR__.'/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$filename='resume_'.$id.'_'.bin2hex(random_bytes(5)).'.pdf';if(move_uploaded_file($f['tmp_name'],$dir.'/'.$filename))$resume='uploads/'.$filename;else $err='Could not save uploaded file.';}}}
if(!$err){$q=$pdo->prepare('UPDATE users SET name=?,department=?,graduation_year=?,skills=?,resume=? WHERE id=?');$q->execute([$name,$dept,$year,$skills,$resume,$id]);$_SESSION['name']=$name;$msg='Profile updated.';header('Location: profile.php?saved=1');exit;}}
include 'header.php';?><div class="row justify-content-center"><div class="col-lg-7"><div class="card p-4"><h2>Edit Profile</h2><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Profile updated.</div><?php endif;?><?php if($err):?><div class="alert alert-danger"><?=h($err)?></div><?php endif;?><form method="post" enctype="multipart/form-data"><label class="form-label">Name</label><input class="form-control mb-3" name="name" value="<?=h($u['name'])?>" required><label class="form-label">Department</label><input class="form-control mb-3" name="department" value="<?=h($u['department'])?>"><label class="form-label">Graduation year</label><input class="form-control mb-3" type="number" name="graduation_year" value="<?=h($u['graduation_year'])?>"><label class="form-label">Skills</label><textarea class="form-control mb-3" name="skills"><?=h($u['skills'])?></textarea><label class="form-label">Resume (PDF, max 2 MB)</label><input class="form-control mb-3" type="file" name="resume" accept="application/pdf"><?php if($u['resume']):?><a href="<?=h($u['resume'])?>" target="_blank">View current resume</a><?php endif;?><button class="btn btn-primary mt-3">Save Profile</button></form></div></div></div><?php include 'footer.php';?>